sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {

    },
	isDatePast: function(){
		// Create GlideDateTime objects for the current date and passed in date
		var rightnow = new GlideDateTime();
		var testdate = new GlideDateTime(strDate);

		// If the testdate is before rightnow, return true, else return false
		if (testdate.before(rightnow)) {
			return true;
		} else {
			return false;
		}
	},
	isDateToday: function(strDate) {
		// Create GlideDateTime objects for the current date and passed in date
		var rightnow = new GlideDateTime();
		var testdate = new GlideDateTime(strDate);

		// If the testdate is today or before, return true, else return false
		if (testdate.onOrBefore(rightnow)) {
			return true;
		} else {
			return false;
		}
	},
    type: 'NeedItUtils'
};
